    let scratch: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: i32 = or_new(runs, 1, 0);
    let b: i32 = or_new(runs, 1, 0);
    let c: i32 = or_new(runs, 2, 0);
    or_set(runs, a, orf_engine(), 2);
    or_set(runs, b, orf_engine(), 2);
    or_set(runs, c, orf_engine(), 2);
    or_set(runs, b, orf_observed_hi(), 1);
    crate::testport::assert_eq(oe_register(table, runs, lines, words, 2, scratch), 0, "registered");
